import React, { useState, useEffect } from "react";
import axios from "axios";

export default function Home() {
  const [books, setBooks] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");

  useEffect(() => {
    axios.get("http://localhost:5000/api/books")
      .then((res) => setBooks(res.data))
      .catch((err) => console.error(err));
  }, []);

  const filteredBooks = books.filter((book) =>
    book.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div
      className="min-h-screen p-8"
      style={{
        background: "linear-gradient(135deg, #1e3c72, #2a5298, #6a11cb, #2575fc)",
        backgroundSize: "400% 400%",
        animation: "gradientShift 10s ease infinite",
      }}
    >
      <style>
        {`
          @keyframes gradientShift {
            0% { background-position: 0% 50%; }
            50% { background-position: 100% 50%; }
            100% { background-position: 0% 50%; }
          }
        `}
      </style>

      <h1 className="text-center text-4xl font-bold text-white mb-6">📚 Welcome to BookStore</h1>

      <div className="flex justify-center mb-8">
        <input
          type="text"
          placeholder="Search for books..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="w-1/2 p-3 rounded-xl text-black text-lg shadow-md focus:outline-none focus:ring-2 focus:ring-blue-400"
          style={{ backgroundColor: "white", color: "black" }}
        />
      </div>

      <div className="grid md:grid-cols-4 sm:grid-cols-2 gap-6">
        {filteredBooks.map((book) => (
          <div
            key={book._id}
            className="bg-white rounded-2xl shadow-lg p-4 text-center transform hover:scale-105 hover:shadow-2xl transition duration-300"
          >
            <img
              src={book.image || "https://via.placeholder.com/150"}
              alt={book.title}
              className="h-40 w-full object-cover rounded-xl mb-4"
            />
            <h3 className="font-semibold text-gray-800">{book.title}</h3>
            <p className="text-sm text-gray-500">{book.author}</p>
            <p className="text-blue-700 font-bold mt-2">${book.price}</p>
          </div>
        ))}
      </div>
    </div>
  );
}
